#include <iostream>
#include <type_traits>

template <typename T>
int describe(T) {
    if constexpr (std::is_integral_v<T>) {
        return 10;
    } else if constexpr (std::is_floating_point_v<T>) {
        return 20;
    } else {
        return 30;
    }
}

int main() {
    int r = describe(3.5);
    std::cout << r;
}
